function camera(g){return{x:clamp(g.player.x-320,0,COLS*T-640),y:clamp(g.player.y-224,0,ROWS*T-448)}}function boat(c,x,y){c.fillStyle="rgba(0,0,0,.18)";c.beginPath();c.ellipse(x,y+13,30,6,0,0,Math.PI*2);c.fill();c.fillStyle="#f2eee0";c.beginPath();c.moveTo(x-31,y-6);c.lineTo(x+31,y-6);c.lineTo(x+20,y+13);c.lineTo(x-22,y+13);c.closePath();c.fill();c.fillStyle="#e55d28";c.fillRect(x-23,y+5,43,5);c.fillStyle="#163e52";c.beginPath();c.moveTo(x-9,y-7);c.lineTo(x-2,y-20);c.lineTo(x+14,y-20);c.lineTo(x+23,y-7);c.closePath();c.fill();c.fillStyle="#8ed3e0";c.fillRect(x,y-17,11,8);c.fillStyle="#333";c.fillRect(x+25,y-4,7,15)}function spawnSchool(g){const p=[[15.5,6.5],[23.5,12.5],[18.5,15.5],[25.5,7.5],[12.5,12.5]],old=g.lastSchoolSpecies;let choices=SCHOOL_SPECIES.filter(id=>id!==old),id=choices[Math.floor(Math.random()*choices.length)],xy=p[Math.floor(Math.random()*p.length)];g.school={speciesId:id,x:xy[0]*T,y:xy[1]*T,expiresAt:Date.now()+120000+Math.floor(Math.random()*45000)};g.lastSchoolSpecies=id}function updateSchool(g){if(g.school&&Date.now()>=g.school.expiresAt){g.school=null;g.nextSchoolAt=Date.now()+30000+Math.random()*45000}if(!g.school&&Date.now()>=(g.nextSchoolAt||0))spawnSchool(g)}function drawSchool(c,g,n){if(!g.school)return;const s=g.school,pulse=.82+Math.sin(n/350)*.12;c.save();c.globalAlpha=.3*pulse;c.fillStyle="#061b28";for(let i=0;i<7;i++){const a=i/7*Math.PI*2+n/1800,r=18+(i%3)*7;c.beginPath();c.ellipse(s.x+Math.cos(a)*r,s.y+Math.sin(a)*r*.55,13,5,a*.1,0,Math.PI*2);c.fill()}c.restore()}function drawMap(c,n,cam,g){c.save();c.translate(-cam.x,-cam.y);for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++){const q=MAP[y][x],X=x*T,Y=y*T;if(q==="W"){c.fillStyle="#287fa8";c.fillRect(X,Y,T,T);c.fillStyle="#66bfd3";const z=Math.floor(n/220+y*2+x)%17;c.fillRect(X+z,Y+8,11,2);c.fillRect(X+(z+9)%19,Y+23,8,2)}else if(q==="P"){c.fillStyle="#78552f";c.fillRect(X,Y,T,T);c.fillStyle="#bc8950";for(let i=2;i<32;i+=8)c.fillRect(X+i,Y+2,5,28)}else if(q==="T"){c.fillStyle="#4f873d";c.fillRect(X,Y,T,T);c.fillStyle="#214e35";c.fillRect(X+3,Y+3,26,23);c.fillStyle="#327249";c.fillRect(X+8,Y,16,8)}else{c.fillStyle=q==="H"?"#d9c38e":(x+y)%2?"#86b957":"#80b153";c.fillRect(X,Y,T,T)}}drawSchool(c,g,n);if(!g.player.inBoat)boat(c,BOAT.x,BOAT.y);c.restore()}function drawPlayer(c,g,n,cam){c.save();c.translate(-cam.x,-cam.y);const x=g.player.x,y=g.player.y;if(g.player.inBoat)boat(c,x,y+5);c.fillStyle="#e8b36d";c.fillRect(x-5,y-12,10,8);c.fillStyle="#1e5968";c.fillRect(x-7,y-5,14,12);c.fillStyle="#e84632";c.fillRect(x-7,y-17,14,5);c.fillRect(x+5,y-14,8,3);c.fillStyle="#f6d34a";c.fillRect(x-4,y-20,10,4);c.fillStyle="#28323c";c.fillRect(x-6,y+7,5,7);c.fillRect(x+2,y+7,5,7);if(["charging","waiting","hooked","battle"].includes(g.mode))drawRod(c,g,n,x,y);c.restore()}function drawRod(c,g,n,x,y){const d=DIR[g.cast?.dir||g.chargeContext?.dir||g.player.facing]||DIR.right,pull=g.mode==="battle"?Math.sin(n/85)*(7+(g.battle?.tension||0)*.08):0,b={x:x+d[0]*7,y:y-7+d[1]*3},tip={x:b.x+d[0]*(31-Math.abs(pull)*.35),y:b.y+d[1]*31+Math.abs(pull)};c.strokeStyle="#4b2d18";c.lineWidth=4;c.beginPath();c.moveTo(b.x,b.y);c.quadraticCurveTo(b.x+d[0]*20-d[1]*pull,b.y+d[1]*20+d[0]*pull,tip.x,tip.y);c.stroke();if(!g.cast||!["waiting","hooked","battle"].includes(g.mode))return;const q=g.cast.target,w=Math.sin(n/170)*(g.mode==="hooked"?5:1.5);c.strokeStyle="#fff";c.lineWidth=1;c.beginPath();c.moveTo(tip.x,tip.y);c.quadraticCurveTo((tip.x+q.x)/2,Math.min(tip.y,q.y)-8-pull,q.x,q.y+w);c.stroke();c.fillStyle="#fff";c.fillRect(q.x-3,q.y-4+w,6,5);c.fillStyle="#e94b35";c.fillRect(q.x-3,q.y-7+w,6,4)}
function loop(g,n){if(game!==g)return;const dt=Math.min(32,n-g.last||16);g.last=n;updateSchool(g);if(g.mode==="explore"){let dx=(g.keys.right?1:0)-(g.keys.left?1:0),dy=(g.keys.down?1:0)-(g.keys.up?1:0);if(dx||dy){if(dx&&dy){dx*=.707;dy*=.707}const z=(g.player.inBoat?.15:.12)*dt,nx=g.player.x+dx*z,ny=g.player.y+dy*z;if(!blocked(g,nx,g.player.y))g.player.x=nx;if(!blocked(g,g.player.x,ny))g.player.y=ny;g.player.facing=Math.abs(dx)>Math.abs(dy)?dx>0?"right":"left":dy>0?"down":"up"}}const cam=camera(g);drawMap(g.ctx,n,cam,g);drawPlayer(g.ctx,g,n,cam);hud(g);g.frame=requestAnimationFrame(t=>loop(g,t))}function tone(f,d=.08){try{const A=window.AudioContext||window.webkitAudioContext;if(!A)return;const a=tone.ctx||(tone.ctx=new A),o=a.createOscillator(),v=a.createGain();o.type="square";o.frequency.value=f;v.gain.setValueAtTime(.035,a.currentTime);v.gain.exponentialRampToValueAtTime(.001,a.currentTime+d);o.connect(v);v.connect(a.destination);o.start();o.stop(a.currentTime+d)}catch(_){}}function splashSound(delay=.3){try{const A=window.AudioContext||window.webkitAudioContext;if(!A)return;const a=tone.ctx||(tone.ctx=new A);if(a.state==="suspended")a.resume();const frames=Math.floor(a.sampleRate*.2),buffer=a.createBuffer(1,frames,a.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<frames;i++)data[i]=(Math.random()*2-1)*(1-i/frames);const source=a.createBufferSource(),filter=a.createBiquadFilter(),gain=a.createGain(),at=a.currentTime+delay;filter.type="lowpass";filter.frequency.setValueAtTime(1400,at);filter.frequency.exponentialRampToValueAtTime(260,at+.18);gain.gain.setValueAtTime(.0001,at);gain.gain.exponentialRampToValueAtTime(.11,at+.018);gain.gain.exponentialRampToValueAtTime(.001,at+.2);source.buffer=buffer;source.connect(filter);filter.connect(gain);gain.connect(a.destination);source.start(at);source.stop(at+.21)}catch(_){}}
function startCharge(g){if(g.mode!=="explore")return action(g);if(nearBoat(g)){g.player.inBoat=true;g.player.x=BOAT.x;g.player.y=BOAT.y;g.player.facing="right";return message(g,"Você embarcou na lancha! Navegue pela represa.",1800)}if(nearDock(g)){g.player.inBoat=false;g.player.x=8.35*T;g.player.y=10.5*T;g.player.facing="left";return message(g,"Você desembarcou no píer.",1500)}const c=context(g);if(!c)return message(g,"Chegue perto de qualquer borda da represa.");g.mode="charging";g.chargeAt=performance.now();g.chargeContext=c}function releaseCharge(g){if(g.mode!=="charging")return;const p=clamp((performance.now()-g.chargeAt)/1600,.08,1),c=g.chargeContext;g.mode="explore";g.chargeContext=null;cast(g,p,c)}function action(g){if(g.mode==="explore")return startCharge(g);if(g.mode==="waiting")return message(g,"Espere a boia afundar...");if(g.mode!=="battle")return;const b=g.battle,ok=b.cursor>=38&&b.cursor<=68;if(ok){b.pulls++;b.tension=Math.max(15,b.tension-18);g.root.querySelector("[data-battle-text]").textContent=`${LINES[b.pulls%LINES.length]} ${b.pulls}/${b.need}`;if(b.pulls>=b.need)caught(g)}else{b.redHits++;b.tension+=12+g.fish.difficulty;g.root.querySelector("[data-battle-text]").textContent=b.redHits===1?"CUIDADO! MAIS UMA NO VERMELHO E ELE FOGE!":"ESCAPOU!";if(b.redHits>=2)return escaped(g,LOSE_QUOTES[(g.fish.uniqueSeed+b.pulls)%LOSE_QUOTES.length]);if(b.tension>=100)escaped(g,LOSE_QUOTES[g.fish.uniqueSeed%LOSE_QUOTES.length])}}
function cast(g,p,c){const target=castTarget(g,c,p);if(!target.steps)return message(g,"Aponte para a água antes de lançar.");const profile=g.player.inBoat?SPOTS[3]:p>.72?SPOTS[2]:p>.38?SPOTS[1]:SPOTS[0],school=g.school&&Date.now()<g.school.expiresAt&&Math.hypot(target.x-g.school.x,target.y-g.school.y)<=T*2.35?g.school.speciesId:null;g.mode="waiting";g.spot={...profile,name:c.name,dir:c.dir};g.cast={power:p,dir:c.dir,target,distance:target.meters,direction:target.direction,origin:g.player.inBoat?"Lancha":c.name,schoolSpeciesId:school};g.progress.stats.totalFishingAttempts++;save(g.progress);message(g,school?"A boia caiu bem na sombra do cardume!":`Boia lançada a ${target.meters.toLocaleString("pt-BR")} m!`,1500);g.waitTimer=setTimeout(()=>{if(game!==g||g.mode!=="waiting")return;if(!school&&Math.random()<.08){g.mode="explore";g.cast=null;return message(g,"Nada mordeu desta vez...",1800)}g.mode="hooked";message(g,"!",500);setTimeout(()=>game===g&&g.mode==="hooked"&&battle(g),450)},1500+Math.random()*1900)}function battle(g){const seed=(Date.now()^Math.floor(Math.random()*0xffffffff))>>>0,spot=g.cast.schoolSpeciesId?{...g.spot,table:{[g.cast.schoolSpeciesId]:1}}:g.spot;g.fish=generateFish(seed,spot);Object.assign(g.fish,{castDistance:g.cast.distance,hookDirection:g.cast.direction,hookPoint:HOOK_POINTS[seed%HOOK_POINTS.length],hookedAt:`${g.cast.origin} • ${g.cast.distance.toLocaleString("pt-BR")} m ao ${g.cast.direction}`,fromSchool:!!g.cast.schoolSpeciesId});g.mode="battle";const p=g.fish.percentile;let need=p<.65?2:p<.82?4:p<.92?6:p<.985?8:10;if(g.fish.speciesId.startsWith("tucunare"))need+=4;g.battle={cursor:0,dir:1,tension:45,pulls:0,need,redHits:0};const box=g.root.querySelector("[data-battle]");box.classList.remove("hidden");box.querySelector("[data-battle-text]").textContent="PUXOU!";g.battleTimer=setInterval(()=>tick(g),45)}function tick(g){if(g.mode!=="battle")return;const b=g.battle;b.cursor+=b.dir*(2.4+g.fish.strength*.11);if(b.cursor>=100||b.cursor<=0){b.dir*=-1;b.cursor=clamp(b.cursor,0,100);b.tension+=1.5+g.fish.strength*.15}b.tension=Math.max(0,b.tension-.35);const box=g.root.querySelector("[data-battle]");box.querySelector("[data-marker]").style.left=`${b.cursor}%`;box.querySelector(".pesca-tension i").style.width=`${Math.min(100,b.tension)}%`;if(b.tension>=100)escaped(g,LOSE_QUOTES[g.fish.uniqueSeed%LOSE_QUOTES.length])}function escaped(g,text){clearInterval(g.battleTimer);g.progress.stats.totalEscaped++;save(g.progress);g.root.querySelector("[data-battle]").classList.add("hidden");g.mode="explore";g.fish=g.cast=null;message(g,text,3200)}function caught(g){clearInterval(g.battleTimer);const c=addCapture(g.progress,g.fish);g.mode="caught";g.root.querySelector("[data-battle]").classList.add("hidden");showCatch(g,c);saveRanking(c)}
function fishArt(canvas,s){const c=canvas.getContext("2d"),draw=img=>{c.clearRect(0,0,canvas.width,canvas.height);if(!img?.naturalWidth){c.fillStyle=s.color;c.fillRect(38,42,170,48);return}c.imageSmoothingEnabled=false;if(s.image)c.drawImage(img,5,2,canvas.width-10,canvas.height-4);else{const w=img.naturalWidth/4,h=img.naturalHeight/3;c.drawImage(img,(s.sprite%4)*w,Math.floor(s.sprite/4)*h,w,h,5,2,canvas.width-10,canvas.height-4)}};fishArt.images||(fishArt.images={});const src=s.image||SPRITE;if(!fishArt.images[src]){const img=fishArt.images[src]=new Image;img.onload=()=>draw(img);img.src=src}draw(fishArt.images[src])}function closeCatch(g){g.root.querySelector("[data-catch]").classList.add("hidden");g.mode="explore";g.fish=g.cast=null}function showCatch(g,c){const s=BY[c.speciesId],old=c.previousRecordWeight,record=c.isPersonalRecord?`<div class="pesca-record-win"><b>NOVO RECORDE!</b><span>${old?`Superou por ${fmt(c.weight-old)}`:"Primeiro recorde da espécie"}</span></div>`:"",quote=c.speciesId.startsWith("tucunare")?`<blockquote>${esc(QUOTES[c.uniqueSeed%QUOTES.length])}</blockquote>`:"",m=g.root.querySelector("[data-catch]");m.innerHTML=`<article class="pesca-catch-card ${c.isPersonalRecord?"is-record":""}"><button class="pesca-catch-close" data-catch-close aria-label="Fechar">×</button><span class="pesca-caught-label">FISGOU!</span><canvas width="260" height="132"></canvas><h2>${esc(s.name)}</h2><p>${esc(s.scientific)}</p><div class="pesca-measures"><strong>${c.length.toLocaleString("pt-BR")} cm</strong><strong>${fmt(c.weight)}</strong></div><div class="pesca-hook-place"><b>Por onde fisgou</b><span>${esc(c.hookPoint||"Pela boca")}</span><small>${esc(c.hookedAt||c.location)}</small></div><div class="pesca-badges"><span>${c.rarity}</span><span>${c.trophyClass}</span><span>${c.bodyCondition}</span>${c.fromSchool?"<span>CARDUME</span>":""}</div>${record}${quote}<small>${new Date(c.capturedAt).toLocaleString("pt-BR")}</small><div class="pesca-catch-actions"><button data-fav="${c.id}">&#9734; Favoritar</button><button data-continue>Continuar</button></div></article>`;m.classList.remove("hidden");fishArt(m.querySelector("canvas"),s);m.querySelector("[data-continue]").onclick=m.querySelector("[data-catch-close]").onclick=()=>closeCatch(g);m.onclick=e=>e.target===m&&closeCatch(g);m.querySelector("[data-fav]").onclick=e=>favorite(g,c.id,e.currentTarget)}function favorite(g,id,b){const s=new Set(g.progress.favorites),c=g.progress.captures.find(x=>x.id===id);s.has(id)?s.delete(id):s.add(id);g.progress.favorites=[...s];if(c)c.isFavorite=s.has(id);save(g.progress);if(b)b.innerHTML=s.has(id)?"&#9733; Favorito":"&#9734; Favoritar"}
function playerId(){let id=localStorage.getItem(PID);if(!id){id=`${Date.now().toString(36)}-${Math.random().toString(36).slice(2,9)}`;localStorage.setItem(PID,id)}return id}function playerName(ask=false){let n=(localStorage.getItem(PNAME)||"").trim().slice(0,30);if(!n&&ask){n=(prompt("Qual seu nome para o Ranking do Olá Pesca?")||"").trim().slice(0,30);if(n)localStorage.setItem(PNAME,n)}return n}async function saveRanking(c){try{if(!window.firebase?.database)return;const name=playerName(true);if(!name)return;const uid=playerId(),now=Date.now();await firebase.database().ref(`jogos/olaPesca/ranking/${uid}`).transaction(v=>{const better=!v||c.weight>+(v.bestWeight||0);return{...(v||{}),name,captures:+(v?.captures||0)+1,bestWeight:better?c.weight:+v.bestWeight,bestLength:better?c.length:+v.bestLength,speciesName:better?c.speciesName:v.speciesName,speciesId:better?c.speciesId:v.speciesId,bestAt:better?now:+v.bestAt||now,updatedAt:now}})}catch(e){console.warn("Ranking do Olá Pesca indisponível",e)}}async function loadRanking(d){const box=d.querySelector("[data-ranking-list]");if(!window.firebase?.database){box.innerHTML=`<p class="pesca-empty">Ranking indisponível agora.</p>`;return}try{const s=await firebase.database().ref("jogos/olaPesca/ranking").orderByChild("bestWeight").limitToLast(50).once("value"),a=[];s.forEach(x=>a.push({...x.val(),id:x.key}));a.sort((x,y)=>+y.bestWeight-+x.bestWeight);box.innerHTML=a.length?a.map((x,i)=>{const f=BY[x.speciesId]||FISH.find(v=>v.name===x.speciesName)||FISH[0];return`<article class="pesca-rank-item ${x.id===playerId()?"me":""}"><b>${i+1}</b><i class="fish-sprite" style="${sprite(f)}"></i><div><strong>${esc(x.name||"Pescador")}</strong><small>${esc(x.speciesName||"Peixe")} • ${(+x.bestLength||0).toLocaleString("pt-BR")} cm</small></div><span>${fmt(+x.bestWeight||0)}</span></article>`}).join(""):`<p class="pesca-empty">Seja o primeiro pescador no ranking!</p>`}catch(_){box.innerHTML=`<p class="pesca-empty">Não foi possível carregar o ranking.</p>`}}
function panel(g,type){const d=g.root.querySelector("[data-drawer]");let title,body;if(type==="dex"){title=`PESCAdex ${Object.keys(g.progress.discovered).length}/13`;body=`<div class="pesca-dex-grid">${FISH.map(s=>{const found=g.progress.discovered[s.id],r=g.progress.records[s.id];return`<article class="${found?"found":"unknown"}"><i class="fish-sprite" style="${sprite(s)}">${found?"":"?"}</i><b>${found?esc(s.name):"Não descoberto"}</b>${r?`<small>Recorde: ${fmt(r.weight)}</small>`:""}</article>`}).join("")}</div>`}else if(type==="captures"){title="Minhas capturas";body=g.progress.captures.length?`<div class="pesca-capture-list">${g.progress.captures.map(c=>`<article><span class="fish-sprite" style="${sprite(BY[c.speciesId])}"></span><div><b>${esc(c.speciesName)}</b><small>${esc(c.hookPoint||"Pela boca")} • ${esc(c.hookedAt||c.location)}</small></div><strong>${fmt(c.weight)}<small>${c.length.toLocaleString("pt-BR")} cm</small></strong><button data-fav="${c.id}">${g.progress.favorites.includes(c.id)?"&#9733;":"&#9734;"}</button></article>`).join("")}</div>`:`<p class="pesca-empty">Sua primeira captura ainda está nadando por aí.</p>`}else if(type==="records"){title="Recordes pessoais";body=`<div class="pesca-record-list">${FISH.map(s=>{const r=g.progress.records[s.id];return`<article><span>${esc(s.name)}</span>${r?`<strong>${fmt(r.weight)}</strong><small>${r.length.toLocaleString("pt-BR")} cm</small>`:"<em>Sem registro</em>"}</article>`}).join("")}</div>`}else if(type==="ranking"){title="Ranking Olá Pesca";body=`<div class="pesca-ranking-head">Maior peixe por pescador</div><div class="pesca-ranking-list" data-ranking-list><p class="pesca-empty">Carregando...</p></div>`}else{title="Como jogar";body=`<div class="pesca-help-copy"><p><b>1.</b> Pesque em qualquer borda da represa.</p><p><b>2.</b> Segure A, Espaço ou Enter: quanto mais tempo, mais longe vai a boia.</p><p><b>3.</b> Embarque na lancha e navegue até o meio.</p><p><b>4.</b> Duas batidas no vermelho fazem o peixe escapar.</p><p><b>5.</b> A sombra do cardume dura pelo menos 2 minutos e mantém a mesma espécie.</p></div>`}d.innerHTML=`<section><header><div><small>OLÁ PESCA</small><h2>${title}</h2></div><button data-close>×</button></header>${body}</section>`;d.classList.remove("hidden");d.querySelector("[data-close]").onclick=()=>d.classList.add("hidden");d.querySelectorAll("[data-fav]").forEach(b=>b.onclick=()=>{favorite(g,b.dataset.fav,b);panel(g,"captures")});if(type==="ranking")loadRanking(d)}
function controls(g){const sig=g.abort.signal,map={ArrowUp:"up",w:"up",W:"up",ArrowDown:"down",s:"down",S:"down",ArrowLeft:"left",ArrowRight:"right",d:"right",D:"right"},isAction=e=>["Space","Enter"].includes(e.code)||(e.code==="KeyA"&&(g.mode!=="explore"||context(g)||nearBoat(g)||nearDock(g)||nearPierLightSwitch(g)));window.addEventListener("keydown",e=>{if(game!==g)return;if(isAction(e)){e.preventDefault();if(!e.repeat)g.mode==="battle"?action(g):startCharge(g);return}const d=e.code==="KeyA"?"left":map[e.key];if(d){e.preventDefault();g.keys[d]=true}},{signal:sig});window.addEventListener("keyup",e=>{if(["Space","Enter","KeyA"].includes(e.code)&&g.mode==="charging")releaseCharge(g);const d=e.code==="KeyA"?"left":map[e.key];if(d)g.keys[d]=false},{signal:sig});g.root.querySelectorAll("[data-dir]").forEach(b=>{const d=b.dataset.dir,start=e=>{e.preventDefault();g.keys[d]=true;b.classList.add("pressed")},end=e=>{e.preventDefault();g.keys[d]=false;b.classList.remove("pressed")};b.addEventListener("pointerdown",start,{signal:sig});for(const n of["pointerup","pointercancel","pointerleave"])b.addEventListener(n,end,{signal:sig})});const a=g.root.querySelector("[data-action]");a.addEventListener("pointerdown",e=>{e.preventDefault();g.mode==="battle"?action(g):startCharge(g)},{signal:sig});for(const n of["pointerup","pointercancel","pointerleave"])a.addEventListener(n,e=>{e.preventDefault();releaseCharge(g)},{signal:sig});g.root.querySelectorAll("[data-panel]").forEach(b=>b.addEventListener("click",()=>panel(g,b.dataset.panel),{signal:sig}));g.root.querySelector("[data-back]").onclick=()=>location.hash="#jogos"}
