drawMap=function(c,n,cam,g){c.save();c.translate(-cam.x,-cam.y);for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++){const q=MAP[y][x],X=x*T,Y=y*T;if(q==="W"){c.fillStyle="#287fa8";c.fillRect(X,Y,T,T);c.fillStyle="#66bfd3";const z=Math.floor(n/220+y*2+x)%17;c.fillRect(X+z,Y+8,11,2);c.fillRect(X+(z+9)%19,Y+23,8,2)}else if(q==="P"){c.fillStyle="#78552f";c.fillRect(X,Y,T,T);c.fillStyle="#bc8950";for(let i=2;i<32;i+=8)c.fillRect(X+i,Y+2,5,28)}else if(q==="T"){c.fillStyle="#4f873d";c.fillRect(X,Y,T,T);c.fillStyle="#214e35";c.fillRect(X+3,Y+3,26,23);c.fillStyle="#327249";c.fillRect(X+8,Y,16,8)}else{c.fillStyle=q==="H"?"#d9c38e":(x+y)%2?"#86b957":"#80b153";c.fillRect(X,Y,T,T)}}drawRaisedBanks(c,n);TREE_POSITIONS.forEach(([x,y,s])=>drawTree(c,x*T,y*T,s));drawSnag(c,n);drawSchool(c,g,n);if(!g.player.inBoat)boat(c,BOAT.x,BOAT.y,"right",false,n);c.restore()};
drawPlayer=function(c,g,n,cam){c.save();c.translate(-cam.x,-cam.y);const x=g.player.x,baseY=g.player.y,facing=g.player.facing||"down",moving=g.mode==="explore"&&Object.values(g.keys).some(Boolean),jumpElapsed=n-(g.distantJump?.startedAt||-9999),startled=!moving&&g.mode==="explore"&&jumpElapsed>=0&&jumpElapsed<900,y=baseY-(startled?Math.abs(Math.sin(jumpElapsed/900*Math.PI))*4:0);if(g.player.inBoat)boat(c,x,y+5,g.player.facing,moving,n);c.fillStyle="#e8b36d";c.fillRect(x-5,y-12,10,8);c.fillStyle="#1e5968";c.fillRect(x-7,y-5,14,12);c.fillStyle="#e84632";c.fillRect(x-7,y-17,14,5);if(facing==="right")c.fillRect(x+5,y-14,8,3);else if(facing==="left")c.fillRect(x-13,y-14,8,3);else if(facing==="down")c.fillRect(x-9,y-14,18,3);else c.fillRect(x-6,y-19,12,3);c.fillStyle="#f6d34a";c.fillRect(x-4,y-20,10,4);c.fillStyle="#26322f";if(facing==="right")c.fillRect(x+2,y-10,2,2);else if(facing==="left")c.fillRect(x-4,y-10,2,2);else if(facing==="down"){c.fillRect(x-4,y-10,2,2);c.fillRect(x+2,y-10,2,2)}else c.fillRect(x-4,y-11,8,2);c.fillStyle="#28323c";c.fillRect(x-6,y+7,5,7);c.fillRect(x+2,y+7,5,7);if(startled){c.fillStyle="#ffdf59";c.font="bold 13px sans-serif";c.textAlign="center";c.fillText("!",x,y-25)}if(["charging","waiting","hooked","battle"].includes(g.mode))drawRod(c,g,n,x,y);c.restore()};
drawRod=function(c,g,n,x,y){const d=DIR[g.cast?.dir||g.chargeContext?.dir||g.player.facing]||DIR.right,pull=g.mode==="battle"?Math.sin(n/85)*(7+(g.battle?.tension||0)*.08):0,b={x:x+d[0]*7,y:y-7+d[1]*3},tip={x:b.x+d[0]*(31-Math.abs(pull)*.35),y:b.y+d[1]*31+Math.abs(pull)};c.strokeStyle="#4b2d18";c.lineWidth=4;c.beginPath();c.moveTo(b.x,b.y);c.quadraticCurveTo(b.x+d[0]*20-d[1]*pull,b.y+d[1]*20+d[0]*pull,tip.x,tip.y);c.stroke();if(!g.cast||!["waiting","hooked","battle"].includes(g.mode))return;const q=g.cast.target,elapsed=n-(g.bobberAnimationAt||0),fighting=["hooked","battle"].includes(g.mode),animating=fighting&&elapsed>=0&&elapsed<560,sink=animating?clamp((elapsed-80)/390,0,1):0,w=g.mode==="waiting"?Math.sin(n/170)*1.5:sink*17;c.strokeStyle="rgba(255,255,255,.9)";c.lineWidth=1;c.beginPath();c.moveTo(tip.x,tip.y);c.quadraticCurveTo((tip.x+q.x)/2,Math.min(tip.y,q.y)-8-pull,q.x,q.y+w);c.stroke();if(g.mode==="waiting"||animating){c.globalAlpha=1-sink*.72;c.strokeStyle="rgba(215,249,255,.8)";c.beginPath();c.ellipse(q.x,q.y+4,8+sink*10,3+sink*4,0,0,Math.PI*2);c.stroke();c.fillStyle="#fff";c.fillRect(q.x-3,q.y-4+w,6,5);c.fillStyle="#e94b35";c.fillRect(q.x-3,q.y-7+w,6,4);c.globalAlpha=1}};
action=function(g){if(g.mode==="explore")return startCharge(g);if(g.mode==="waiting")return message(g,"Espere a boia afundar...");if(g.mode!=="battle")return;const b=g.battle,ok=b.cursor>=38&&b.cursor<=68;if(ok){g.bobberAnimationAt=performance.now();tone(245,.06);b.pulls++;b.tension=Math.max(15,b.tension-18);g.root.querySelector("[data-battle-text]").textContent=`${LINES[b.pulls%LINES.length]} ${b.pulls}/${b.need}`;if(b.pulls>=b.need)caught(g)}else{b.redHits++;b.tension+=12+g.fish.difficulty;g.root.querySelector("[data-battle-text]").textContent=b.redHits===1?"CUIDADO! MAIS UMA NO VERMELHO E ELE FOGE!":"ESCAPOU!";if(b.redHits>=2)return escaped(g,LOSE_QUOTES[(g.fish.uniqueSeed+b.pulls)%LOSE_QUOTES.length]);if(b.tension>=100)escaped(g,LOSE_QUOTES[g.fish.uniqueSeed%LOSE_QUOTES.length])}};
cast=function(g,p,c){const target=castTarget(g,c,p);if(!target.steps)return message(g,"Aponte para a água antes de lançar.");const base=g.player.inBoat?SPOTS[3]:p>.72?SPOTS[2]:p>.38?SPOTS[1]:SPOTS[0],nearSnag=Math.hypot(target.x-SNAG.x,target.y-SNAG.y)<=SNAG.radius,profile=nearSnag?{...SPOTS[3],id:"galhada",name:"Galhada dos peixes grandes",bonus:.16}:{...base},school=g.school&&Date.now()<g.school.expiresAt&&Math.hypot(target.x-g.school.x,target.y-g.school.y)<=T*2.35?g.school.speciesId:null;g.mode="waiting";g.spot={...profile,name:nearSnag?profile.name:c.name,dir:c.dir};g.cast={power:p,dir:c.dir,target,distance:target.meters,direction:target.direction,origin:g.player.inBoat?"Lancha":c.name,schoolSpeciesId:school,nearSnag};g.progress.stats.totalFishingAttempts++;save(g.progress);message(g,school?"A boia caiu bem na sombra do cardume!":nearSnag?"A boia caiu junto à galhada. Aqui vivem peixes maiores!":`Boia lançada a ${target.meters.toLocaleString("pt-BR")} m!`,1800);g.waitTimer=setTimeout(()=>{if(game!==g||g.mode!=="waiting")return;if(!school&&!nearSnag&&Math.random()<.08){g.mode="explore";g.cast=null;return message(g,"Nada mordeu desta vez...",1800)}g.mode="hooked";g.bobberAnimationAt=performance.now();message(g,"!",500);setTimeout(()=>game===g&&g.mode==="hooked"&&battle(g),450)},1500+Math.random()*1900)};
battle=function(g){const seed=(Date.now()^Math.floor(Math.random()*0xffffffff))>>>0,spot=g.cast.schoolSpeciesId?{...g.spot,table:{[g.cast.schoolSpeciesId]:1}}:g.spot;g.fish=generateFish(seed,spot);Object.assign(g.fish,{castDistance:g.cast.distance,hookDirection:g.cast.direction,hookPoint:HOOK_POINTS[seed%HOOK_POINTS.length],hookedAt:`${g.cast.origin} • ${g.cast.distance.toLocaleString("pt-BR")} m ao ${g.cast.direction}`,fromSchool:!!g.cast.schoolSpeciesId,nearSnag:!!g.cast.nearSnag});g.mode="battle";g.bobberAnimationAt=performance.now();const p=g.fish.percentile;let need=p<.65?2:p<.82?4:p<.92?6:p<.985?8:10;if(g.fish.speciesId.startsWith("tucunare"))need+=4;g.battle={cursor:0,dir:1,tension:45,pulls:0,need,redHits:0};const box=g.root.querySelector("[data-battle]");box.classList.remove("hidden");box.querySelector("[data-battle-text]").textContent="PUXOU!";g.battleTimer=setInterval(()=>tick(g),45)};
